inline ::flatbuffers::Offset<SSYPlacement> CreateSSYPlacement(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    ::flatbuffers::Offset<EXOParameter> GALACTIC_L_DEG = 0,
    ::flatbuffers::Offset<EXOParameter> GALACTIC_B_DEG = 0,
    ::flatbuffers::Offset<EXOParameter> SUPERGALACTIC_X_KPC = 0,
    ::flatbuffers::Offset<EXOParameter> SUPERGALACTIC_Y_KPC = 0,
    ::flatbuffers::Offset<EXOParameter> SUPERGALACTIC_Z_KPC = 0,
    ::flatbuffers::Offset<EXOParameter> DISTANCE_GALACTIC_CENTER_KPC = 0,
    ::flatbuffers::Offset<EXOParameter> DISTANCE_M31_KPC = 0,
    ::flatbuffers::Offset<EXOParameter> DISTANCE_LOCAL_GROUP_KPC = 0,
    ::flatbuffers::Offset<EXOParameter> DISTANCE_HOST_KPC = 0,
    ::flatbuffers::Offset<::flatbuffers::String> FRAME_NOTE = 0) {
  SSYPlacementBuilder builder_(_fbb);
  builder_.add_FRAME_NOTE(FRAME_NOTE);
  builder_.add_DISTANCE_HOST_KPC(DISTANCE_HOST_KPC);
  builder_.add_DISTANCE_LOCAL_GROUP_KPC(DISTANCE_LOCAL_GROUP_KPC);
  builder_.add_DISTANCE_M31_KPC(DISTANCE_M31_KPC);
  builder_.add_DISTANCE_GALACTIC_CENTER_KPC(DISTANCE_GALACTIC_CENTER_KPC);
  builder_.add_SUPERGALACTIC_Z_KPC(SUPERGALACTIC_Z_KPC);
  builder_.add_SUPERGALACTIC_Y_KPC(SUPERGALACTIC_Y_KPC);
  builder_.add_SUPERGALACTIC_X_KPC(SUPERGALACTIC_X_KPC);
  builder_.add_GALACTIC_B_DEG(GALACTIC_B_DEG);
  builder_.add_GALACTIC_L_DEG(GALACTIC_L_DEG);
  return builder_.Finish();
}

struct SSYPlacement::Traits {
  using type = SSYPlacement;
  static auto constexpr Create = CreateSSYPlacement;
};

inline ::flatbuffers::Offset<SSYPlacement> CreateSSYPlacementDirect(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    ::flatbuffers::Offset<EXOParameter> GALACTIC_L_DEG = 0,
    ::flatbuffers::Offset<EXOParameter> GALACTIC_B_DEG = 0,
    ::flatbuffers::Offset<EXOParameter> SUPERGALACTIC_X_KPC = 0,
    ::flatbuffers::Offset<EXOParameter> SUPERGALACTIC_Y_KPC = 0,
    ::flatbuffers::Offset<EXOParameter> SUPERGALACTIC_Z_KPC = 0,
    ::flatbuffers::Offset<EXOParameter> DISTANCE_GALACTIC_CENTER_KPC = 0,
    ::flatbuffers::Offset<EXOParameter> DISTANCE_M31_KPC = 0,
    ::flatbuffers::Offset<EXOParameter> DISTANCE_LOCAL_GROUP_KPC = 0,
    ::flatbuffers::Offset<EXOParameter> DISTANCE_HOST_KPC = 0,
    const char *FRAME_NOTE = nullptr) {
  auto FRAME_NOTE__ = FRAME_NOTE ? _fbb.CreateString(FRAME_NOTE) : 0;
  return CreateSSYPlacement(
      _fbb,
      GALACTIC_L_DEG,
      GALACTIC_B_DEG,
      SUPERGALACTIC_X_KPC,
      SUPERGALACTIC_Y_KPC,
      SUPERGALACTIC_Z_KPC,
      DISTANCE_GALACTIC_CENTER_KPC,
      DISTANCE_M31_KPC,
      DISTANCE_LOCAL_GROUP_KPC,
      DISTANCE_HOST_KPC,
      FRAME_NOTE__);
}

